/**
 * A timestamp such as "2h ago", or the moment itself, in a `<time>` element (`design/components/relative-time.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/relative-time.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  derived,
  devWarning,
  relativeTimePhrase,
  useMember,
  watchEffect,
} from '@polymorph/angular'

export interface RelativeTimeMessages {
  both: (moment: string, distance: string) => string
}

/** A timestamp such as "2h ago", or the moment itself, in a `<time>` element: the inputs it takes, by the React member's prop names. */
export interface RelativeTimeProps {
  /**
   * Intl's `style` without `short`, which looks like `narrow`. Named `format` (NumberInput's
   * word) because the governed-props law and `no-raw-styles` read any JSX `style` as raw CSS. In
   * the absolute form it is the date's length: `narrow` is Intl's `medium` date ("Aug 4, 2026"),
   * `long` its `long` date.
   */
  format?: 'long' | 'narrow'
  /**
   * The locale `Intl` formats with; defaults to the page's own.
   */
  locale?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: RelativeTimeMessages
  /**
   * What it says: the distance from now (`relative`, the default), the moment itself
   * (`absolute`, "Aug 4, 2026, 2:05 PM"), or both, joined by `messages.both` ("Aug 4, 2026, 2:05
   * PM (2h ago)"), for a place where the exact moment matters. An instant is written in the time
   * zone of whatever renders the member: the reader's in a browser, the server's on a server.
   */
  mode?: 'both' | 'relative' | 'absolute'
  /**
   * Intl's `numeric` option. `always` (the default) suits scanned queue metadata ("1 day ago");
   * prose surfaces pass `auto` for "yesterday".
   */
  numeric?: 'always' | 'auto'
  /**
   * ISO-8601 with the chart tier's calendar-date rules (`docs/charts.md`): a date-only string is
   * a **calendar date**, not shifted by timezone ("2026-08-04" is the 4th everywhere), and a
   * full timestamp keeps its offset.
   */
  value: string
}

/** A timestamp such as "2h ago", or the moment itself, in a `<time>` element. */
@Component({
  selector: 'pm-relative-time',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  // prettier-ignore
  template: `@if (e1()) {<time
[attr.datetime]="e2()"
data-member="relative-time"
>{{ e3() }}</time>}`,
})
export class RelativeTime {
  /**
   * Intl's `style` without `short`, which looks like `narrow`. Named `format` (NumberInput's
   * word) because the governed-props law and `no-raw-styles` read any JSX `style` as raw CSS. In
   * the absolute form it is the date's length: `narrow` is Intl's `medium` date ("Aug 4, 2026"),
   * `long` its `long` date.
   */
  readonly format = input<
    Exclude<RelativeTimeProps['format'], undefined>,
    RelativeTimeProps['format']
  >('narrow', {
    transform: (value: RelativeTimeProps['format']) => (value === undefined ? 'narrow' : value),
  })
  /**
   * The locale `Intl` formats with; defaults to the page's own.
   */
  readonly locale = input<RelativeTimeProps['locale']>(undefined)
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  readonly messages = input<RelativeTimeProps['messages']>(undefined)
  /**
   * What it says: the distance from now (`relative`, the default), the moment itself
   * (`absolute`, "Aug 4, 2026, 2:05 PM"), or both, joined by `messages.both` ("Aug 4, 2026, 2:05
   * PM (2h ago)"), for a place where the exact moment matters. An instant is written in the time
   * zone of whatever renders the member: the reader's in a browser, the server's on a server.
   */
  readonly mode = input<Exclude<RelativeTimeProps['mode'], undefined>, RelativeTimeProps['mode']>(
    'relative',
    { transform: (value: RelativeTimeProps['mode']) => (value === undefined ? 'relative' : value) },
  )
  /**
   * Intl's `numeric` option. `always` (the default) suits scanned queue metadata ("1 day ago");
   * prose surfaces pass `auto` for "yesterday".
   */
  readonly numeric = input<
    Exclude<RelativeTimeProps['numeric'], undefined>,
    RelativeTimeProps['numeric']
  >('always', {
    transform: (value: RelativeTimeProps['numeric']) => (value === undefined ? 'always' : value),
  })
  /**
   * ISO-8601 with the chart tier's calendar-date rules (`docs/charts.md`): a date-only string is
   * a **calendar date**, not shifted by timezone ("2026-08-04" is the 4th everywhere), and a
   * full timestamp keeps its offset.
   */
  readonly value = input.required<RelativeTimeProps['value']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      format: () => this.format(),
      locale: () => this.locale(),
      messages: () => this.messages(),
      mode: () => this.mode(),
      numeric: () => this.numeric(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly phrase = derived(() =>
    relativeTimePhrase(this.$p.value, {
      locale: this.$p.locale,
      numeric: this.$p.numeric,
      format: this.$p.format,
      mode: this.$p.mode,
      messages: this.$p.messages,
    }),
  )

  constructor() {
    watchEffect(
      () => this.phrase.value,
      () => this.effect1(),
      true,
    )
  }

  protected e1() {
    return this.phrase.value !== null
  }

  protected e2() {
    if (!(this.phrase.value !== null)) return undefined as never
    return this.$p.value
  }

  protected e3() {
    if (!(this.phrase.value !== null)) return undefined as never
    return this.phrase.value
  }

  private effect1(): void {
    devWarning(
      this.phrase.value === null,
      `RelativeTime could not parse "${this.$p.value}" — rendering nothing.`,
    )
  }
}
